// commit-msg hook: node scripts/check-commit-msg.mjs <file>
// CI (PR titles): node scripts/check-commit-msg.mjs --text "<title>"
import { readFileSync } from 'node:fs'
import { validateMessage } from './conventions.mjs'

const [flag, value] = process.argv.slice(2)
const text = flag === '--text' ? value : readFileSync(flag, 'utf8')

// Messages generated by git itself (merging main back into dev, reverts) are allowed
if (/^(Merge (branch|remote-tracking branch|pull request) |Revert ")/.test(text)) process.exit(0)

const error = validateMessage(text ?? '')
if (error) {
  console.error(`✗ ${error}\n  Got: ${(text ?? '').split('\n')[0]}`)
  process.exit(1)
}
